import bpy

bl_info = {
    "name": "AI Mesh Cleanup Tool",
    "author": "3DFlowHub",
    "version": (1, 0, 0),
    "blender": (4, 0, 0),
    "location": "View3D > Sidebar > AI Cleanup",
    "description": "Cleans up AI-generated meshes for production pipelines.",
    "category": "Object",
}

class AI_OT_CleanupMesh(bpy.types.Operator):
    bl_idname = "object.ai_cleanup_mesh"
    bl_label = "Run AI Mesh Cleanup"
    bl_options = {'REGISTER', 'UNDO'}

    def execute(self, context):
        selected_objects = [obj for obj in context.selected_objects if obj.type == 'MESH']
        if not selected_objects:
            self.report({'WARNING'}, "No mesh objects selected")
            return {'CANCELLED'}

        for obj in selected_objects:
            context.view_layer.objects.active = obj

            # Apply rotation and scale
            bpy.ops.object.transform_apply(location=False, rotation=True, scale=True)

            # Enter edit mode to clean geometry
            bpy.ops.object.mode_set(mode='EDIT')
            bpy.ops.mesh.select_all(action='SELECT')

            # Merge by distance (duplicate vertices)
            bpy.ops.mesh.remove_doubles(threshold=0.0001)

            # Delete loose vertices
            bpy.ops.mesh.delete_loose()

            bpy.ops.object.mode_set(mode='OBJECT')

        self.report({'INFO'}, f"Successfully cleaned {len(selected_objects)} mesh(es).")
        return {'FINISHED'}

class AI_PT_CleanupPanel(bpy.types.Panel):
    bl_label = "AI Mesh Cleanup"
    bl_idname = "AI_PT_CleanupPanel"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "AI Cleanup"

    def draw(self, context):
        layout = self.layout
        layout.operator("object.ai_cleanup_mesh", icon='TOOL_SETTINGS')

classes = (
    AI_OT_CleanupMesh,
    AI_PT_CleanupPanel,
)

def register():
    for cls in classes:
        bpy.utils.register_class(cls)

def unregister():
    for cls in classes:
        bpy.utils.unregister_class(cls)

if __name__ == "__main__":
    register()
